from hran_radio.radio_classes.radio_5_1_single_NAHKA_dualband import Radio5_1SingleNAHKADualBand
from hran_radio.radio_output_parser.five_one_parser import RadioOutputParser


class Radio5_1SingleNAHKATripleBand(Radio5_1SingleNAHKADualBand):
    """
In dictionary self.physical_antenna_map key is path from frmon map and value is physical RM antenna pipe
    """

    def __init__(self, radio_ip, sm_ip, msm_ip):
        super(Radio5_1SingleNAHKATripleBand, self).__init__(radio_ip, sm_ip, msm_ip)
        self.radio_connection.set_frmon_ip("127.0.0.1")
        self.parser = RadioOutputParser()
        self.physical_antenna_map = {
            "ant1": "ant1",
            "ant2": "ant1",
            "ant3": "ant1",
            "ant4": "ant2",
            "ant5": "ant2",
            "ant6": "ant2",
            "ant7": "ant3",
            "ant8": "ant3",
            "ant9": "ant3",
            "ant10": "ant4",
            "ant11": "ant4",
            "ant12": "ant4",
        }

    @staticmethod
    def get_map_cmd_for(trx, first_ant_num=1, last_ant_num=12):
        """
        Generate tx or rx map command

        :param trx: 'tx' or 'rx' str
        :param first_ant_num: default 1 int
        :param last_ant_num: default 8 int
        :return: full command
        :rtype: str
        """
        cmd_a = [
            "/ action create AntennaPath /ant{num}_hran_radio /rf/ant{num}".format(num=num)
            for num in range(first_ant_num, last_ant_num + 1)
        ]
        cmd_b = [
            "/ant{num}_hran_radio get {trx}_carrier_ids".format(num=num, trx=trx)
            for num in range(first_ant_num, last_ant_num + 1)
        ]
        return "\n".join(cmd_a + cmd_b)
